import hashlib, hmac, os, sqlite3

def hash_password(pw, salt=None):
    salt = salt or os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pw.encode(), salt, 200_000)
    return salt.hex() + '$' + digest.hex()

def check_password(pw, stored):
    salt_hex, digest_hex = stored.split('$')
    digest = hashlib.pbkdf2_hmac('sha256', pw.encode(), bytes.fromhex(salt_hex), 200_000)
    return hmac.compare_digest(digest.hex(), digest_hex)

db = sqlite3.connect(':memory:')
db.execute('CREATE TABLE users (name TEXT UNIQUE, pw TEXT)')
db.execute('INSERT INTO users VALUES (?, ?)', ('asha', hash_password('s3cret!')))

def login(name, pw):
    row = db.execute('SELECT pw FROM users WHERE name = ?', (name,)).fetchone()
    return row is not None and check_password(pw, row[0])

print(login('asha', 's3cret!'), login('asha', 'guess'), login("x' OR '1'='1", 'anything'))

